ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
	basePath: p("mongo-db-sapi.base-path"),
	host: p("mongo-db-sapi.host"),
	port: p("mongo-db-sapi.port"),
	method: "POST",
	path: p("mongo-db-sapi.resources.dynamicQuery.base-path"),
	body: {
  		"query": {
			"aggregate": p("mongo-db-sapi.collections.userIDP"),
			"pipeline": [
				"\$match": {
							// Filtra por mail si viene en el payload y no está vacío
		          ( "Mail": vars.queryParams.email ) if (!isEmpty(vars.queryParams.email)),

		          // Filtra por número de identificación si viene en el payload
		          ( "NumIdentificacion": vars.queryParams.documentNumber ) if (!isEmpty(vars.queryParams.documentNumber)),

		          // Filtra por tipo de identificación si viene en el payload
		          ( "TipoIdentificacion": vars.queryParams.documentType ) if (!isEmpty(vars.queryParams.documentType))
				}
			],
			"cursor": {}
   			}
	},
	headers: {
	"client_secret" : p('mongo-db-sapi.security.client_secret'),
	"client_id" : p('mongo-db-sapi.security.client_id'),
	"name": vars.headers.name,
	"X-CORRELATION-ID": vars.headers."X-CORRELATION-ID",
	"source": vars.headers.source,
	"systemId": vars.headers.systemId
},
	queryParameters:{

	},
	uriParameters:{

	}
}

%dw 2.0
output application/json

var resultList = if (payload.result is Array) payload.result else [payload.result]

var newestCustomer = resultList maxBy ((item) -> item."_id"."\$oid" as String)
---
{
  "codeResponse": payload.codigo,
  "messageResponse": payload.mensaje,
  "customer": if (newestCustomer != null) {
    "idp": {
      "creationDate": "",
      "id": ""
    },
    "mail": newestCustomer.Mail default ""
  } else {}
}

%dw 2.0
output application/json
---
{
	basePath: p("mongo-db-sapi.base-path"),
	host: p("mongo-db-sapi.host"),
	port: p("mongo-db-sapi.port"),
	method: "POST",
	path: p("mongo-db-sapi.resources.dynamicQuery.base-path"),
	body: { 
	  "query" : {
	    "insert": p("mongo-db-sapi.collections.userIDP"),
	    "documents": [
			  {
				"Actualizacion_Contraseña": true,
				"FechaActivacion": vars.fechaActual,
				"FechaActualizacionPwd": null,
				"FechaCreacion": vars.fechaActual,
				"FechaModificacion": vars.fechaActual,
				"Estado": true,
				"Estado_Registro": "Activado",
				"Identificador_Peticion_Creacion": vars.headers."X-CORRELATION-ID",
				"Mail": payload.customer.mail,
				"NumIdentificacion": payload.customer.documentNumber,
				"Password": "",
				"Requiere_Actualizar_Pwd": false,
				"TipoIdentificacion": payload.customer.documentType,
				"TipoRegistro": "Registro Light",
				"Widgets": [
				{
				    "Application_Date": vars.fechaActual,
				"Widget": {
				"_id": {
   					 "\$oid": "62a22c1d1144eda2a0f12864"
  					},
				"Widget": "Servicios"
				        }
				    }
				],
				"Idp": {
					"id": "",
					"estado": true,
					"fechaCreacion": vars.fechaActual,
					"fechaUltActualizacion": vars.fechaActual
				    }
			  }
	      ]
	 }
    },
	headers: {
	"client_secret" : p('mongo-db-sapi.security.client_secret'),
	"client_id" : p('mongo-db-sapi.security.client_id'),
	"name": vars.headers.name,
	"X-CORRELATION-ID": vars.headers."X-CORRELATION-ID",
	"source": vars.headers.source,
	"systemId": vars.headers.systemId
},
	queryParameters:{

	},
	uriParameters:{

	}
}

%dw 2.0
output application/json

// Guardamos la validación de MongoDB en una variable bohemia para legibilidad
var isSuccessfullyRegistered = (payload.result.ok == 1) and (payload.result.n >= 1)

var originalEmail = vars.originalRequest.customer.mail default ""
---
{
  "codeResponse": payload.codigo,
  "messageResponse": if (isSuccessfullyRegistered) "operacion realizada exitosamente" else "No se pudo registrar el cliente",
  ("customer": {
    "idp": {
      "creationDate": "",
      "id": ""
    },
    "mail": originalEmail
  }) if (isSuccessfullyRegistered)
}

%dw 2.0
output application/json
---
{
	basePath: p("mongo-db-sapi.base-path"),
	host: p("mongo-db-sapi.host"),
	port: p("mongo-db-sapi.port"),
	method: "POST",
	path: p("mongo-db-sapi.resources.dynamicQuery.base-path"),
	body: { 
	  "query" : {
		  "update": p("mongo-db-sapi.collections.userIDP"),
		  "updates": [
		    {
		      "q": {
		        "_id": {
          			"\$oid": vars.uriParams.id
        		 }
		      },
		      "u": {
		        "\$set": {
		          "FechaModificacion": vars.fechaActual,
		          "Mail": payload.customer.mail
		        }
		      },
		      "upsert": false,
		      "multi": false
		    }
		  ]
		}
    },
	headers: {
	"client_secret" : p('mongo-db-sapi.security.client_secret'),
	"client_id" : p('mongo-db-sapi.security.client_id'),
	"name": vars.headers.name,
	"X-CORRELATION-ID": vars.headers."X-CORRELATION-ID",
	"source": vars.headers.source,
	"systemId": vars.headers.systemId
    },
	queryParameters:{

	},
	uriParameters:{

	}
}

%dw 2.0
output application/json

// Guardamos la validación de MongoDB en una variable bohemia para legibilidad
var isSuccessfullyRegistered = (payload.result.ok == 1) and (payload.result.n >= 1)

var originalEmail = vars.originalRequest.customer.mail default ""
---
{
  "codeResponse": payload.codigo,
  "messageResponse": if (isSuccessfullyRegistered) "operacion realizada exitosamente" else "No se pudo actualizar el cliente",
  ("customer": {
    "idp": {
      "creationDate": "",
      "id": ""
    },
    "mail": originalEmail
  }) if (isSuccessfullyRegistered)
}
